import { createMemo, createSignal, mergeProps, Show, type ComponentProps, type ParentComponent } from "solid-js";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { ImageCacheProvider } from "#core/ui-next/components/image-cache.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { OrnateFrame, type OrnateFrameProps } from "#core/ui-next/components/ornate-panel.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { Popup, PopupContextProvider } from "#core/ui-next/components/popup.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import PopupSequencer from "#base/ui/popup-sequencer/popup-sequencer.js";
import { YieldStatusBar } from "#base/ui-next/components/yield-status-bar.jsx";

export const enum ScreenFrameCloseHandler {
	ContextManager,
	PopupSequencer,
}

export interface ScreenFrameComponentProps extends ComponentProps<"div"> {
	name: string;
	panelContext: string;
	audioContext: string;
	ornatePanelData: OrnateFrameProps;
	onClosing?: () => void;
	title?: string;
	wip?: boolean;
	hideClose?: boolean;
	doNotStretch?: boolean;
	addYieldBar?: boolean;
	isFullscreen?: boolean;

	/**
	 * Default is ContextManager.
	 */
	closeHandler?: ScreenFrameCloseHandler;

	onContextChanged?: (activatedElement: Element, deactivatedElement: Element) => void;
}

const ScreenFrameComponent: ParentComponent<ScreenFrameComponentProps> = (props) => {
	const [popupContext, setPopupContext] = createSignal<PopupContextProvider>();
	const isSmallScreen = useIsSmallScreen();

	const mergedProps = mergeProps({ addYieldBar: true }, props);

	function close() {
		// NOTE: This is also handled in `<Panel>` when listening for the close-panel event.
		if (props.onClosing) {
			props.onClosing();
		}

		switch (props.closeHandler ?? ScreenFrameCloseHandler.ContextManager) {
			case ScreenFrameCloseHandler.ContextManager:
				ContextManager.pop(props.panelContext);
				break;
			case ScreenFrameCloseHandler.PopupSequencer:
				PopupSequencer.closePopup(props.panelContext);
				break;
		}
	}

	function handleCancelInput() {
		if (props.hideClose) {
			return;
		} else if (popupContext()?.active()) {
			popupContext()?.close();
		} else {
			close();
		}
	}

	const showTitle = createMemo(() => {
		return props.title != null;
	});

	const ornateFrameClass = createMemo(() => {
		const aspectRatio = props.doNotStretch ? "menu-aspect-ratio-fixed" : "menu-aspect-ratio";
		return `${aspectRatio} flex flex-col items-center ${props.isFullscreen ? "size-full" : "max-w-screen max-h-screen"}`;
	});

	return (
		<Panel
			name={props.name}
			id={props.panelContext}
			class="flex justify-center"
			onCancelInput={handleCancelInput}
			ref={props.ref}
			onContextChanged={props.onContextChanged}
		>
			<AudioContextProvider segment={props.audioContext}>
				<ImageCacheProvider>
					<Show when={!isSmallScreen() && mergedProps.addYieldBar}>
						<YieldStatusBar />
					</Show>
					<Popup setPopupContext={setPopupContext}>
						<OrnateFrame
							{...props.ornatePanelData}
							hideTopIcon={isSmallScreen() || props.isFullscreen}
							useNoMarginFrame={isSmallScreen() || props.isFullscreen}
							class={ornateFrameClass()}
							isFullscreen={props.isFullscreen}
						>
							<Show when={props.wip}>
								<div class="absolute top-12 left-3 bottom-0 wip-banner" />
							</Show>
							<Show when={showTitle()}>
								<Filigree.TitleAccent
									class={`mb-2 mx-24 ${isSmallScreen() || props.isFullscreen ? "mt-2" : "-mt-2"}`}
								>
									<Header class={`max-w-full text-center justify-center`}>
										<L10n.Compose text={props.title!} />
									</Header>
								</Filigree.TitleAccent>
							</Show>

							{props.children}

							<Show when={!props.hideClose}>
								{
									// NOTE: This position is temporary.
									// The close button sizing and position relative to the outer frame need to be investigated.
								}
								<CloseButton
									class={`${isSmallScreen() ? "right-1 top-1" : "right-4 top-5"} absolute`}
									onActivate={() => close()}
									hotkeyAction="cancel"
									navTrayText="LOC_GENERIC_CLOSE"
								/>
							</Show>
						</OrnateFrame>
						<Popup.Output class="fullscreen child-fullscreen" />
					</Popup>
				</ImageCacheProvider>
			</AudioContextProvider>
		</Panel>
	);
};

export const ScreenFrame = ComponentRegistry.register({
	name: "ScreenFrame",
	//styles: [style],
	images: ["blp:wip_label"],
	createInstance: ScreenFrameComponent,
});
